fn get_data_column_sidecars<P: Preset>(
    signed_block_header: SignedBeaconBlockHeader,
    kzg_commitments: &ContiguousList<KzgCommitment, P::MaxBlobCommitmentsPerBlock>,
    kzg_commitments_inclusion_proof: BlobCommitmentsInclusionProof<P>,
    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
    let blob_count = kzg_commitments.len();
    ensure!(
        cells_and_kzg_proofs.len() == blob_count,
        Error::BlobCommitmentsLengthMismatch {
            blob_count,
            commitments_length: kzg_commitments.len(),
        }
    );

    let mut sidecars = vec![];
    for column_index in 0..P::NumberOfColumns::USIZE {
        let column = ContiguousList::try_from_iter(
            (0..blob_count)
                .map(|row_index| cells_and_kzg_proofs[row_index].0[column_index].clone()),
        )?;
        let kzg_proofs = ContiguousList::try_from_iter(
            (0..blob_count).map(|row_index| cells_and_kzg_proofs[row_index].1[column_index]),
        )?;

        sidecars.push(
            DataColumnSidecar {
                index: ColumnIndex::try_from(column_index)?,
                column,
                kzg_commitments: kzg_commitments.clone(),
                kzg_proofs,
                signed_block_header,
                kzg_commitments_inclusion_proof,
            }
            .into(),
        );
    }

    Ok(sidecars)
}

pub fn construct_data_column_sidecars<P: Preset>(
    signed_block: &SignedBeaconBlock<P>,
    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
    let signed_block_header = signed_block.to_header();
    let Some(post_electra_beacon_block_body) = signed_block.message().body().post_electra() else {
        return Ok(vec![]);
    };

    let kzg_commitments = post_electra_beacon_block_body.blob_kzg_commitments();
    if kzg_commitments.is_empty() {
        return Ok(vec![]);
    }

    let kzg_commitments_inclusion_proof =
        misc::kzg_commitments_inclusion_proof(post_electra_beacon_block_body);

    get_data_column_sidecars(
        signed_block_header,
        kzg_commitments,
        kzg_commitments_inclusion_proof,
        cells_and_kzg_proofs,
    )
}

pub fn construct_data_column_sidecars_from_sidecar<P: Preset>(
    data_column_sidecar: &DataColumnSidecar<P>,
    cells_and_kzg_proofs: &[CellsAndKzgProofs<P>],
) -> Result<Vec<Arc<DataColumnSidecar<P>>>> {
    let DataColumnSidecar {
        kzg_commitments,
        signed_block_header,
        kzg_commitments_inclusion_proof,
        ..
    } = data_column_sidecar;

    get_data_column_sidecars(
        *signed_block_header,
        kzg_commitments,
        *kzg_commitments_inclusion_proof,
        cells_and_kzg_proofs,
    )
}

pub fn try_convert_to_cells_and_kzg_proofs<P: Preset>(
    blobs: &[Blob<P>],
    cell_proofs: &[KzgProof],
    backend: KzgBackend,
) -> Result<Vec<CellsAndKzgProofs<P>>> {
    let expected_proofs_length = blobs.len() * P::CellsPerExtBlob::USIZE;
    ensure!(
        cell_proofs.len() == expected_proofs_length,
        Error::InvalidCellsProofsLength {
            expected: expected_proofs_length,
            proofs_length: cell_proofs.len(),
        }
    );

    );

    Ok(proof)
}

pub fn kzg_commitments_inclusion_proof<P: Preset>(
    body: &(impl PostElectraBeaconBlockBody<P> + ?Sized),
) -> BlobCommitmentsInclusionProof<P> {
    let depth = P::KzgCommitmentsInclusionProofDepth::USIZE;
    let mut proof = BlobCommitmentsInclusionProof::<P>::default();

    proof[depth - 4] = body.bls_to_execution_changes().hash_tree_root();

    proof[depth - 3] = hashing::hash_256_256(
        body.sync_aggregate().hash_tree_root(),
        body.execution_payload().hash_tree_root(),
    );

    proof[depth - 2] = hashing::hash_256_256(
        hashing::hash_256_256(body.execution_requests().hash_tree_root(), ZERO_HASHES[0]),
        ZERO_HASHES[1],
    );

    proof[depth - 1] = hashing::hash_256_256(
        hashing::hash_256_256(
            hashing::hash_256_256(
                body.randao_reveal().hash_tree_root(),
                body.eth1_data().hash_tree_root(),
            ),
            hashing::hash_256_256(body.graffiti(), body.proposer_slashings().hash_tree_root()),
        ),
        hashing::hash_256_256(
            hashing::hash_256_256(body.attester_slashings_root(), body.attestations_root()),
            hashing::hash_256_256(
                body.deposits().hash_tree_root(),
                body.voluntary_exits().hash_tree_root(),
            ),
        ),
    );

    proof
}

