pub const fn index_at_commitment_depth<P: Preset>(commitment_index: BlobIndex) -> u64 {
    // When using the minimal preset, `commitment_index` should be in the range `0..16`.
    // 16 is the value of `MAX_BLOB_COMMITMENTS_PER_BLOCK`.
    //
    // The Merkle tree that makes up Deneb `BeaconBlockBody` looks like this:
    // ```text
    // 1┬─2┬─4┬─8┬16 body.randao_reveal
    //  │  │  │  └17 body.eth1_data
    //  │  │  └─9┬18 body.graffiti
    //  │  │     └19 body.proposer_slashings
    //  │  └─5┬10┬20 body.attester_slashings
    //  │     │  └21 body.attestations
    //  │     └11┬22 body.deposits
    //  │        └23 body.voluntary_exits
    //  └─3──6┬12┬24 body.sync_aggregate
    //        │  └25 body.execution_payload
    //        └13┬26 body.bls_to_execution_changes
    //           └27 body.blob_kzg_commitments
    //
    // 27┬─54┬108┬216┬432┬864 body.blob_kzg_commitments[0]
    //   │   │   │   │   └865 body.blob_kzg_commitments[1]
    //   │   │   │   └433┬866 body.blob_kzg_commitments[2]
    //   │   │   │       └867 body.blob_kzg_commitments[3]
    //   │   │   └217┬434┬868 body.blob_kzg_commitments[4]
    //   │   │       │   └869 body.blob_kzg_commitments[5]
    //   │   │       └435┬870 body.blob_kzg_commitments[6]
    //   │   │           └871 body.blob_kzg_commitments[7]
    //   │   └109┬218┬436┬872 body.blob_kzg_commitments[8]
    //   │       │   │   └873 body.blob_kzg_commitments[9]
    //   │       │   └437┬874 body.blob_kzg_commitments[10]

pub fn kzg_commitments_inclusion_proof<P: Preset>(
    body: &(impl PostElectraBeaconBlockBody<P> + ?Sized),
) -> BlobCommitmentsInclusionProof<P> {
    let depth = P::KzgCommitmentsInclusionProofDepth::USIZE;
    let mut proof = BlobCommitmentsInclusionProof::<P>::default();

    proof[depth - 4] = body.bls_to_execution_changes().hash_tree_root();

    proof[depth - 3] = hashing::hash_256_256(
        body.sync_aggregate().hash_tree_root(),
        body.execution_payload().hash_tree_root(),
    );

    proof[depth - 2] = hashing::hash_256_256(
        hashing::hash_256_256(body.execution_requests().hash_tree_root(), ZERO_HASHES[0]),
        ZERO_HASHES[1],
    );

    proof[depth - 1] = hashing::hash_256_256(
        hashing::hash_256_256(
            hashing::hash_256_256(
                body.randao_reveal().hash_tree_root(),
                body.eth1_data().hash_tree_root(),
            ),
            hashing::hash_256_256(body.graffiti(), body.proposer_slashings().hash_tree_root()),
        ),
        hashing::hash_256_256(
            hashing::hash_256_256(body.attester_slashings_root(), body.attestations_root()),
            hashing::hash_256_256(
                body.deposits().hash_tree_root(),
                body.voluntary_exits().hash_tree_root(),
            ),
        ),
    );

    proof
}

